"""Additional original glossary for chapters 24–33; plain text definitions."""

GLOSSARY = [
    ("Область конфигурации Git", "Уровень, к которому относится настройка: системный, пользовательский, репозиторный, отдельное рабочее дерево или текущий вызов команды. Область помогает определить приоритет, но для параметров с несколькими значениями дополнительно требуется учитывать правила их объединения."),
    ("Источник конфигурации Git", "Конкретный файл или иной канал, из которого прочитано значение настройки. Вывод git config --show-origin позволяет связать неожиданное поведение с местом задания значения, а --show-scope дополнительно показывает его область."),
    ("includeIf", "Условное подключение дополнительного файла настроек Git. Например, условие gitdir проверяет расположение служебного каталога репозитория и позволяет применять учебную личность только к выбранным проектам; доступные условия зависят от версии Git."),
    ("Command scope", "Область настроек, переданных непосредственно текущему запуску Git, например через -c или набор переменных GIT_CONFIG_COUNT. Она позволяет изменить поведение одного вызова без записи в личные файлы; явный -c имеет преимущество над парами этого набора переменных."),
    ("Многозначная настройка Git", "Параметр конфигурации, у которого может одновременно существовать несколько записей. Для него недостаточно рассуждения о единственном победившем значении: команда и сам параметр определяют, используются ли все записи, последняя либо другой специально установленный набор."),
    ("Псевдоним Git", "Сохранённое сокращение команды в разделе alias конфигурации. Обычный псевдоним разворачивается в аргументы Git, а значение с начальным восклицательным знаком запускается оболочкой и потому имеет иной порядок обработки и дополнительные возможности исполнения."),
    ("GIT_PREFIX", "Переменная, с помощью которой Git сообщает некоторым вспомогательным запускам исходный подкаталог относительно корня рабочего дерева. Она особенно полезна для оболочечного псевдонима: сам псевдоним начинает работу от корня, а переменная сохраняет сведения о месте, из которого его вызвали."),
    ("Peeling", "Последовательное раскрытие ссылки объекта аннотированной метки до её целевого объекта. Выражение v1^{commit} дополнительно требует получить именно коммит и завершится ошибкой, если цепочка приводит к несовместимому типу."),
    ("Commit-ish", "Выражение, которое Git может разрешить в коммит, в том числе имя ветки или метку, ведущую к коммиту. Термин описывает допустимый вход команды, а не отдельный тип хранимого объекта; при строгой проверке используют явное требование ^{commit}."),
    ("Tree-ish", "Выражение, из которого Git может получить дерево файлов: например, само дерево либо коммит с корневым деревом. Конкретная команда определяет допустимые формы входа, поэтому наличие похожего имени ещё не доказывает совместимость объекта с требуемой операцией."),
    ("Буквальный pathspec", "Правило выбора пути, в котором специальные символы шаблона считаются обычными символами имени. Запись :(literal)src/x[1].txt выбирает файл с квадратными скобками; кавычки оболочки сами по себе не отключают дальнейшее распознавание шаблона внутри Git."),
    ("Магия pathspec", "Явные модификаторы синтаксиса выбора путей Git, записываемые после начального двоеточия. Они позволяют указать буквальное сопоставление, привязку к корню, правила шаблона или исключение, не полагаясь на случайное толкование имени файла."),
    ("Top pathspec", "Модификатор выбора пути, который привязывает сопоставление к корню рабочего дерева даже при вызове из вложенного каталога. Он изменяет базу сопоставления, но не обязан менять способ печати найденных имён конкретной командой."),
    ("Exclude pathspec", "Исключающее правило выбора путей, которое убирает совпавшие имена из результата других положительных правил. Оно ограничивает выбранный набор для команды и не удаляет соответствующие файлы или объекты из репозитория."),
    ("Цепочка первых родителей", "Маршрут по истории, на каждом слиянии продолжающийся через первого родителя коммита. Он помогает рассматривать последовательность интеграции в основную линию, но скрывает отдельные шаги присоединённых веток, если дополнительно их не исследовать."),
    ("Git bisect", "Двоичный поиск изменения между известным исправным и известным неисправным состоянием истории. Git выбирает промежуточные коммиты, а человек или проверочная программа классифицирует их; правильность результата зависит от проверяемого признака и воспроизводимости проверки."),
    ("Bisect run", "Автоматический режим классификации выбранных коммитов заданной проверочной программой. После каждого перехода Git запускает её заново, поэтому программа должна проверять именно текущие исходники и не принимать старый результат сборки за новое измерение."),
    ("Код 125 в bisect", "Особый код завершения проверочной программы, сообщающий, что выбранный коммит нельзя достоверно классифицировать. Он позволяет пропустить состояние, например несовместимое со стендом, но множество таких пропусков может оставить несколько возможных причин вместо единственного найденного коммита."),
    ("Git grep", "Поиск текста в выбранном представлении файлов проекта. Без дополнительных параметров он исследует отслеживаемые рабочие файлы, с --cached читает индекс, а при указании дерева может искать в сохранённом снимке без переключения рабочей копии."),
    ("Git blame", "Сопоставление строк выбранного файла с коммитами, к которым Git относит их происхождение в исследуемой истории. Результат помогает найти контекст изменения, но не доказывает, что названный автор является причиной ошибки или последним человеком, осмысленно проверившим строку."),
    ("Хук Git", "Программа, вызываемая Git при определённом событии, например перед созданием коммита или обновлением серверных ссылок. Её вход, допустимый отказ и момент выполнения зависят от события; наличие локальной программы не создаёт обязательного правила для всех участников."),
    ("Pre-commit", "Локальный хук перед продолжением создания коммита, чей ненулевой код завершения может остановить операцию. Он должен учитывать подготовленный индекс: проверка только рабочих файлов способна исследовать другие байты, чем те, которые попадут в коммит."),
    ("Commit-msg", "Локальный хук проверки или изменения подготовленного сообщения коммита. Он получает путь к файлу сообщения, а не весь текст стандартным вводом; его можно обойти предусмотренным для commit параметром --no-verify."),
    ("Pre-push", "Локальный хук перед передачей обновлений при push, получающий сведения о локальных и удалённых ссылках через стандартный ввод. Он удобен для ранней проверки, но окончательное ограничение принятия изменений должно обеспечиваться контролируемой принимающей стороной."),
    ("Pre-receive", "Принимающий серверный хук, который один раз получает весь набор предлагаемых обновлений ссылок. Ненулевой код отклоняет весь набор до обновления ссылок, поэтому такой хук подходит для правил, требующих согласованного решения по нескольким веткам."),
    ("Update hook", "Принимающий хук, вызываемый отдельно для каждой обновляемой ссылки с её именем и прежним и новым идентификаторами. Его отказ относится к соответствующему обновлению; без дополнительных гарантий атомарности другие ссылки той же отправки могут быть приняты."),
    ("Reference transaction", "Согласованная группа изменений ссылок, для которой Git сообщает хуку этапы выполнения. В проверенном Git 2.43 наблюдались prepared и committed; отказ на подготовленном этапе может остановить обновление, тогда как последующее уведомление не является возвратом уже выполненной записи."),
    ("Карантин объектов Git", "Отдельная область, в которой принимающая сторона временно размещает поступившие объекты до завершения проверок приёма. Хук видит эти объекты через подготовленное Git окружение; его бездумная очистка способна сделать только что переданные данные недоступными для самой проверки."),
    (".gitmodules", "Отслеживаемый файл описания вложенных репозиториев, содержащий соответствие их имён, путей и исходных адресов. Он не хранит содержимое вложенного проекта и не заменяет локальные настройки доступа; изменение этого файла само по себе не обновляет все существующие локальные копии."),
    ("Файл перенаправления .git", "Обычный текстовый файл с указанием фактического служебного каталога Git вместо самостоятельного каталога .git внутри рабочего дерева. Такая организация используется, в частности, для подмодулей и дополнительных рабочих деревьев, поэтому проверка только наличия каталога .git недостаточна."),
    ("Рекурсивное обновление подмодулей", "Обход вложенных репозиториев с выполнением соответствующей операции также для их собственных зависимостей. Он способен обращаться к нескольким адресам и использовать транспортные настройки, поэтому перед запуском необходимо понимать состав и происхождение всей цепочки вложений."),
    ("Promisor remote", "Источник объектов частичной копии, который обещает предоставить отсутствующие из-за фильтрации объекты при последующем запросе. Наличие такого обещания позволяет Git отличать предусмотренную неполноту от обычного отсутствия данных, но фактическая доступность источника всё равно необходима."),
    ("Ленивая загрузка объектов Git", "Получение отсутствующего обещанного объекта только тогда, когда операция действительно потребовала его содержимое. Это уменьшает первоначальный перенос, но команда чтения файла может неожиданно обратиться к источнику и потребовать сеть даже после завершённого clone."),
    ("Поверхностная граница истории", "Объявленная граница, за которой поверхностная копия временно не рассматривает дальнейших родителей коммитов. Она сокращает доступный граф и влияет на поиск предков и общих оснований; наличие всех файлов текущего снимка не означает наличие полной истории."),
    ("Sparse checkout", "Режим материализации только выбранной части путей в рабочем дереве. Он уменьшает число видимых файлов и стоимость некоторых операций с ними, но сам по себе не удаляет остальные объекты из базы и не ограничивает сохранённую историю."),
    ("Указатель Git LFS", "Небольшой текстовый объект Git, содержащий версию формата, SHA-256 и размер отдельно хранимого большого содержимого. Наличие такого указателя в коммите не доказывает, что соответствующие байты доступны на LFS-сервере или подготовлены для автономной работы."),
    ("Git LFS Batch API", "Интерфейс согласования передачи внешних LFS-объектов, позволяющий запросить операции над несколькими идентификаторами. Ответ может содержать конкретные адреса и параметры загрузки или отправки; сам обмен объектами остаётся отдельным от обычного хранения blob-объектов Git."),
    ("Git bundle", "Переносимый файл с объявленными ссылками и упакованными объектами Git, пригодный для обмена без постоянного соединения. Он может быть полным или требовать ранее полученную историю; внешние LFS-данные и содержимое самостоятельных подмодулей автоматически в него не включаются."),
    ("Предпосылка bundle", "Коммит, который должен уже существовать в принимающем репозитории для использования неполного bundle. Проверка git bundle verify сопоставляет предпосылки с доступной историей: одинаковое имя метки без нужного объекта не удовлетворяет требованию."),
    ("Bundle unbundle", "Операция чтения bundle с добавлением содержащихся в нём объектов в базу принимающего репозитория. Сама по себе она не передвигает main на объявленную отправителем вершину; обновление ссылок нужно выполнить отдельной понятной операцией."),
    ("Pkt-line", "Формат обрамления сообщений ряда протоколов Git с шестнадцатеричным полем длины. Это единица прикладного обмена, а не сетевой IP-пакет; для объяснения задержки транспорта требуется учитывать дополнительные нижележащие уровни."),
    ("Git upload-pack", "Принимающая сторона получения объектов клиентом, несмотря на непривычное с точки зрения клиента слово upload. Она участвует в объявлении возможностей и согласовании нужных объектов при fetch или clone; транспорт может доставлять её обмен через SSH или HTTP."),
    ("Git receive-pack", "Принимающая сторона отправки объектов и предложений обновить ссылки при push. Она выполняет соответствующие проверки и хуки перед принятием изменений; успешная передача байтов ещё не означает принятие каждой предложенной ссылки."),
    ("Smart HTTP Git", "Режим обмена Git поверх HTTP, в котором сервер выполняет протокольную обработку запросов получения или отправки объектов. Он отличается от простой раздачи заранее подготовленных файлов и требует собственного контроля доступа, маршрутизации запросов и настройки серверного исполнения."),
    ("Principal подписи", "Идентификатор подписанта, с которым проверяющая политика связывает разрешённый открытый ключ. Его наличие в файле доверия является правилом проверяющего, а не автоматическим доказательством совпадения с email автора коммита или владельцем учётной записи сервера."),
    ("Allowed signers", "Файл правил принятия SSH-подписей, связывающий разрешённые имена с открытыми ключами и дополнительными ограничениями. Одна и та же математически корректная подпись может не пройти принятие Git после изменения этого файла, потому что изменилось основание доверия."),
    ("Пространство имён подписи", "Обозначение назначения SSH-подписи, позволяющее ограничить применение ключа определённым видом подтверждения. В учебном файле разрешённых подписантов используется назначение git; это разделение протоколов не устанавливает личность владельца ключа само по себе."),
    ("Отзыв ключа", "Изменение политики, после которого соответствующий ключ перестают принимать в предусмотренных ею случаях. Отзыв отличается от изменения байтов подписанного объекта: прежняя подпись может оставаться математически корректной, но уже не удовлетворять действующим правилам доверия."),
    ("Подписанная метка", "Аннотированный объект метки, включающий криптографическую подпись своих данных и ссылку на целевой объект. Проверка такой метки не означает автоматическую проверку подписи каждого коммита её истории и не связывает произвольный архив с выбранными исходниками без дополнительных свидетельств."),
    ("Signed-off-by", "Строка установленного формата в сообщении коммита, добавляемая, в частности, параметром commit -s. Её смысл определяется правилами проекта; она не является криптографической подписью и не заменяет действие commit -S."),
    ("Git-filter-repo", "Отдельный инструмент преобразования истории Git, например для исключения выбранных путей из прежних снимков. Переписывание создаёт другие объекты и требует проверки копии, зависимостей и дальнейшего переключения участников; инструмент не гарантирован одной установкой Git."),
    ("Commit map", "Карта соответствия прежних и новых идентификаторов коммитов после преобразования истории. Она помогает переводить сохранённые ссылки и объяснять исчезнувшие коммиты, но не является доказательством функциональной эквивалентности программы или полной очистки внешних хранилищ."),
    ("Trace2", "Механизм событий выполнения Git, позволяющий исследовать начало и завершение команд, области работы и дочерние процессы. Формат JSON удобен для сопоставления, но вложенные длительности могут перекрываться и не должны бездумно суммироваться."),
    ("GIT_TRACE_PACKET", "Переменная включения журнала прикладного протокольного обмена Git. Такой журнал способен показать согласование ссылок и объектов, но не заменяет захват сетевых пакетов и может содержать частные имена, идентификаторы и другие служебные сведения."),
    ("Git fsck", "Проверка связности и корректности объектов, доступных исследуемому репозиторию. Сообщение о недостижимом объекте не обязательно означает повреждение, а успешная техническая проверка не доказывает правильность приложения и отсутствие нежелательного содержимого."),
    ("Connectivity-only", "Ускоренный режим fsck, сосредоточенный на наличии и связности нужных объектов. Он не заменяет полную проверку содержимого blob-объектов, поэтому подходит только для утверждений, которым достаточно такого ограниченного охвата."),
]
